-- Counterexample: fabricated default entities in a hypothetical retail model.
-- These rows are not real business entities.
insert into customer (customer_id, customer_name) values (0, 'Unknown Customer');
insert into campaign (campaign_id, campaign_name) values (0, 'No Campaign');
insert into associate (associate_id, associate_name) values (0, 'Unassigned Associate');

create table retail_order_bad (
  order_id integer primary key,
  order_number text not null unique,
  order_total numeric(12,2) not null,
  customer_id integer not null references customer(customer_id),
  campaign_id integer not null references campaign(campaign_id),
  associate_id integer not null references associate(associate_id)
);

-- This row says the order has a customer, campaign, and associate.
-- In reality, none of those relationships exists.
insert into retail_order_bad
  (order_id, order_number, order_total, customer_id, campaign_id, associate_id)
values
  (1001, 'R-1001', 42.50, 0, 0, 0);

CREATE TABLE customer (
    customer_id bigint PRIMARY KEY,
    customer_name text NOT NULL
);

CREATE TABLE product (
    product_id bigint PRIMARY KEY,
    sku text NOT NULL UNIQUE,
    product_name text NOT NULL
);

CREATE TABLE retail_order (
    order_id bigint PRIMARY KEY,
    customer_id bigint NOT NULL REFERENCES customer(customer_id),
    placed_at timestamp NOT NULL
);

CREATE TABLE order_item (
    order_id bigint NOT NULL REFERENCES retail_order(order_id),
    line_no integer NOT NULL CHECK (line_no > 0),
    product_id bigint NOT NULL REFERENCES product(product_id),
    quantity integer NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (order_id, line_no)
);

CREATE TABLE customer_profile (
    customer_id bigint PRIMARY KEY REFERENCES customer(customer_id),
    marketing_email text NOT NULL UNIQUE,
    created_at timestamp NOT NULL
);

CREATE TABLE customer (
    customer_id        bigint PRIMARY KEY,
    email              varchar(320) NOT NULL UNIQUE
);

CREATE TABLE order_header (
    order_id           bigint PRIMARY KEY,
    customer_id        bigint NOT NULL REFERENCES customer (customer_id),
    order_date         date NOT NULL
);

CREATE TABLE order_line (
    order_id           bigint NOT NULL,
    line_number        integer NOT NULL,
    sku                varchar(64) NOT NULL,
    quantity           integer NOT NULL CHECK (quantity > 0),
    unit_price_cents   integer NOT NULL CHECK (unit_price_cents >= 0),

    PRIMARY KEY (order_id, line_number),
    FOREIGN KEY (order_id) REFERENCES order_header (order_id)
);

CREATE TABLE customer (
  customer_id      bigint PRIMARY KEY,
  email            text NOT NULL UNIQUE,
  created_at       timestamp NOT NULL
);

CREATE TABLE product (
  product_id       bigint PRIMARY KEY,
  sku              text NOT NULL UNIQUE,
  active           boolean NOT NULL DEFAULT true
);

CREATE TABLE retail_order (
  order_id         bigint PRIMARY KEY,
  customer_id      bigint NOT NULL REFERENCES customer(customer_id),
  order_status     text NOT NULL CHECK (order_status IN ('draft', 'placed', 'paid', 'cancelled')),
  placed_at        timestamp NOT NULL
);

CREATE TABLE order_line (
  order_id         bigint NOT NULL REFERENCES retail_order(order_id),
  line_number      integer NOT NULL,
  product_id       bigint NOT NULL REFERENCES product(product_id),
  quantity         integer NOT NULL CHECK (quantity > 0),
  unit_price_cents integer NOT NULL CHECK (unit_price_cents >= 0),
  PRIMARY KEY (order_id, line_number)
);

CREATE TABLE payment_event (
  payment_event_id bigint PRIMARY KEY,
  order_id         bigint NOT NULL REFERENCES retail_order(order_id),
  payment_status   text NOT NULL CHECK (payment_status IN ('authorized', 'captured', 'refunded', 'failed')),
  amount_cents     integer NOT NULL CHECK (amount_cents >= 0),
  occurred_at      timestamp NOT NULL
);

CREATE TABLE shipment_event (
  shipment_event_id bigint PRIMARY KEY,
  order_id          bigint NOT NULL REFERENCES retail_order(order_id),
  carrier_code      text NOT NULL,
  occurred_at       timestamp NOT NULL
);
